/*--------------------------------------------------------------
# Font & Color Variables
# Help: https://bootstrapmade.com/color-system/
--------------------------------------------------------------*/
/* Fonts */
:root {
    --default-font:
        "Roboto", system-ui, -apple-system, "Segoe UI", Roboto,
        "Helvetica Neue", Arial, "Noto Sans", "Liberation Sans", sans-serif,
        "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
        "Noto Color Emoji";
    --heading-font: "Ubuntu", sans-serif;
    --nav-font: "Nunito", sans-serif;
}

/* Global Colors - The following color variables are used throughout the website. Updating them here will change the color scheme of the entire website */
:root,
body[data-theme="light"] {
    --background-color: #f4f9ff; /* Background utama situs yang terang, nyaman untuk mata */
    --default-color: #1d3557; /* Warna teks utama agar kontras di background terang */
    --heading-color: #112b46; /* Warna heading yang lebih gelap agar jelas */
    --accent-color: #3b8ff9; /* Biru muda bersih sebagai accent utama */
    --surface-color: #ffffff; /* Surface box/card putih bersih */
    --contrast-color: #12314f; /* Warna teks di atas area accent */
    --sidebar-bg: #ffffff;
    --sidebar-border: rgba(17, 43, 70, 0.12);
    --sidebar-icon-bg: #edf5ff;
    --sidebar-icon-border: rgba(18, 49, 79, 0.08);
    --nav-color: rgba(
        17,
        41,
        72,
        0.72
    ); /* Warna link nav agar terbaca di background terang */
    --nav-hover-color: #12314f; /* Warna hover nav yang tegas tapi tetap adem */
    --nav-mobile-background-color: #edf5ff; /* Background menu mobile terang */
    --nav-dropdown-background-color: #f2f8ff; /* Background dropdown yang lembut */
    --nav-dropdown-color: #12314f; /* Teks dropdown agar nyaman dibaca */
    --nav-dropdown-hover-color: #0d2d4d; /* Hover dropdown */
}

body[data-theme="dark"] {
    --background-color: #1f1f1f; /* Background asli gelap sebelum ubah warna */
    --default-color: #ffffff; /* Teks utama putih */
    --heading-color: #ffffff; /* Heading putih */
    --accent-color: #ececec; /* Accent asli gelap */
    --surface-color: #232323; /* Surface kartu gelap */
    --contrast-color: #310606; /* Kontras untuk teks pada area accent */
    --sidebar-bg: #1f1f1f;
    --sidebar-border: rgba(255, 255, 255, 0.08);
    --sidebar-icon-bg: rgba(255, 255, 255, 0.05);
    --sidebar-icon-border: rgba(255, 255, 255, 0.08);
    --nav-color: rgba(236, 236, 236, 0.59);
    --nav-hover-color: #ffffff;
    --nav-mobile-background-color: #393939;
    --nav-dropdown-background-color: #393939;
    --nav-dropdown-color: #ffffff;
    --nav-dropdown-hover-color: #ececec;
}

/* Color Presets - These classes override global colors when applied to any section or element, providing reuse of the sam color scheme. */

.light-background {
    --background-color: #f7fbff;
    --surface-color: #ffffff;
    --default-color: #1d3557;
    --heading-color: #112b46;
}

.dark-background {
    --background-color: #0f172a;
    --default-color: #edf4ff;
    --heading-color: #ffffff;
    --surface-color: #1b2433;
    --contrast-color: #0f172a;
}

/* Smooth scroll */
:root {
    scroll-behavior: smooth;
}

/*--------------------------------------------------------------
  # General Styling & Shared Classes
  --------------------------------------------------------------*/
body {
    color: var(--default-color);
    background-color: var(--background-color);
    font-family: var(--default-font);
}

a {
    color: var(--accent-color);
    text-decoration: none;
    transition: 0.3s;
}

a:hover {
    color: color-mix(in srgb, var(--accent-color), transparent 25%);
    text-decoration: none;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    color: var(--heading-color);
    font-family: var(--heading-font);
}

/* PHP Email Form Messages
  ------------------------------*/
.php-email-form .error-message {
    display: none;
    background: #df1529;
    color: #ffffff;
    text-align: left;
    padding: 15px;
    margin-bottom: 24px;
    font-weight: 600;
}

.php-email-form .sent-message {
    display: none;
    color: #ffffff;
    background: #059652;
    text-align: center;
    padding: 15px;
    margin-bottom: 24px;
    font-weight: 600;
}

.php-email-form .loading {
    display: none;
    background: var(--surface-color);
    text-align: center;
    padding: 15px;
    margin-bottom: 24px;
}

.php-email-form .loading:before {
    content: "";
    display: inline-block;
    border-radius: 50%;
    width: 24px;
    height: 24px;
    margin: 0 10px -6px 0;
    border: 3px solid var(--accent-color);
    border-top-color: var(--surface-color);
    animation: php-email-form-loading 1s linear infinite;
}

@keyframes php-email-form-loading {
    0% {
        transform: rotate(0deg);
    }

    100% {
        transform: rotate(360deg);
    }
}

/*--------------------------------------------------------------
  # Global Header
  --------------------------------------------------------------*/
.header {
    --background-color: var(--sidebar-bg);
    --contrast-color: var(--contrast-color);
    color: var(--default-color);
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    padding: 0 15px;
    width: 300px;
    transition: all ease-in-out 0.3s;
    overflow-y: auto;
    z-index: 997;
    background-color: var(--sidebar-bg);
}

.header .header-container {
    border-radius: 20px;
    padding: 15px;
    background-color: var(--sidebar-bg);
    border: 1px solid var(--sidebar-border);
    box-shadow: 0 12px 35px rgba(75, 121, 190, 0.08);
}

.header .social-links {
    margin: 0 0 10px 0;
}

.header .social-links a {
    font-size: 16px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: var(--sidebar-icon-bg);
    color: var(--heading-color);
    margin: 0 2px;
    border-radius: 50%;
    text-align: center;
    width: 40px;
    height: 40px;
    transition: 0.3s;
    border: 1px solid var(--sidebar-icon-border);
}

.header .social-links a:hover {
    color: var(--contrast-color);
    background: var(--accent-color);
}

@media (min-width: 1200px) {
    .header ~ main,
    .header ~ #footer {
        margin-left: 330px;
    }
}

@media (max-width: 1199px) {
    .header {
        left: -100%;
    }
}

.header.header-show {
    left: 0;
}

.header .header-toggle {
    color: var(--contrast-color);
    background-color: var(--accent-color);
    font-size: 22px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    position: fixed;
    top: 15px;
    right: 15px;
    z-index: 9999;
    transition: background-color 0.3s;
}

.header .header-toggle:hover {
    color: var(--contrast-color);
    background-color: color-mix(in srgb, var(--accent-color) 90%, white 15%);
}

/*--------------------------------------------------------------
# Navigation Menu
--------------------------------------------------------------*/
.mobile-nav-toggle {
    display: none;
}

.navmenu {
    padding: 0;
    z-index: 9997;
    width: 100%;
}

.navmenu ul {
    list-style: none;
    padding: 0 0 20px 0;
    margin: 0;
}

.navmenu a,
.navmenu a:focus {
    color: var(--nav-color);
    padding: 15px 10px;
    font-family: var(--nav-font);
    font-size: 16px;
    font-weight: 400;
    display: flex;
    align-items: center;
    white-space: nowrap;
    transition: 0.3s;
    width: 100%;
}

.navmenu a .navicon,
.navmenu a:focus .navicon {
    font-size: 20px;
    margin-right: 10px;
}

.navmenu a .toggle-dropdown,
.navmenu a:focus .toggle-dropdown {
    font-size: 12px;
    line-height: 0;
    margin-left: auto;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: 0.3s;
    flex-shrink: 0;
    background-color: color-mix(in srgb, var(--accent-color), transparent 90%);
}

.navmenu a .toggle-dropdown:hover,
.navmenu a:focus .toggle-dropdown:hover {
    background-color: var(--accent-color);
    color: var(--contrast-color);
}

.navmenu a:hover,
.navmenu .active,
.navmenu .active:focus {
    color: var(--nav-hover-color);
}

.navmenu a:hover .navicon,
.navmenu .active .navicon,
.navmenu .active:focus .navicon {
    color: var(--accent-color);
}

.navmenu .active .toggle-dropdown,
.navmenu .active:focus .toggle-dropdown {
    background-color: var(--accent-color);
    color: var(--contrast-color);
    transform: rotate(180deg);
}

.navmenu .dropdown {
    display: block;
}

.navmenu .dropdown a,
.navmenu .dropdown a:focus {
    color: var(--nav-dropdown-color);
}

.navmenu .dropdown a:hover,
.navmenu .dropdown .active,
.navmenu .dropdown .active:focus {
    color: var(--nav-dropdown-hover-color);
}

.navmenu .dropdown ul {
    position: static;
    display: none;
    z-index: 99;
    padding: 5px 10px;
    margin: 5px 10px;
    background-color: var(--nav-dropdown-background-color);
    border: 1px solid color-mix(in srgb, var(--default-color), transparent 90%);
    box-shadow: none;
    transition: all 0.5s ease-in-out;
}

.navmenu .dropdown ul ul {
    background-color: color-mix(
        in srgb,
        var(--nav-dropdown-background-color),
        transparent 25%
    );
}

.navmenu .dropdown > .dropdown-active {
    display: block;
    background-color: color-mix(
        in srgb,
        var(--nav-dropdown-background-color),
        transparent 12%
    );
}

/*--------------------------------------------------------------
# Global Footer
--------------------------------------------------------------*/
.footer {
    color: var(--default-color);
    background-color: var(--background-color);
    font-size: 14px;
    padding: 0 0 40px 0;
    position: relative;
}

.footer .copyright {
    padding-top: 40px;
    border-top: 1px solid
        color-mix(in srgb, var(--default-color), transparent 90%);
}

.footer .copyright p {
    margin-bottom: 0;
}

.footer .credits {
    margin-top: 4px;
    font-size: 13px;
    text-align: center;
}

/*--------------------------------------------------------------
# Preloader
--------------------------------------------------------------*/
#preloader {
    position: fixed;
    inset: 0;
    z-index: 999999;
    overflow: hidden;
    background: var(--background-color);
    transition: all 0.6s ease-out;
}

#preloader:before {
    content: "";
    position: fixed;
    top: calc(50% - 30px);
    left: calc(50% - 30px);
    border: 6px solid #ffffff;
    border-color: var(--accent-color) transparent var(--accent-color)
        transparent;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    animation: animate-preloader 1.5s linear infinite;
}

@keyframes animate-preloader {
    0% {
        transform: rotate(0deg);
    }

    100% {
        transform: rotate(360deg);
    }
}

/*--------------------------------------------------------------
# Scroll Top Button
--------------------------------------------------------------*/
.scroll-top {
    position: fixed;
    visibility: hidden;
    opacity: 0;
    right: 15px;
    bottom: -15px;
    z-index: 99999;
    background-color: var(--accent-color);
    width: 44px;
    height: 44px;
    border-radius: 50px;
    transition: all 0.4s;
}

.scroll-top i {
    font-size: 24px;
    color: var(--contrast-color);
    line-height: 0;
}

.scroll-top:hover {
    background-color: color-mix(in srgb, var(--accent-color), transparent 20%);
    color: var(--contrast-color);
}

.scroll-top.active {
    visibility: visible;
    opacity: 1;
    bottom: 15px;
}

/*--------------------------------------------------------------
# Disable aos animation delay on mobile devices
--------------------------------------------------------------*/
@media screen and (max-width: 768px) {
    [data-aos-delay] {
        transition-delay: 0 !important;
    }
}

/*--------------------------------------------------------------
# Global Page Titles & Breadcrumbs
--------------------------------------------------------------*/
.page-title {
    color: var(--default-color);
    padding: 25px 0 0 0;
    position: relative;
}

.page-title .container {
    border-bottom: 1px solid
        color-mix(in srgb, var(--default-color), transparent 90%);
    padding-bottom: 25px;
}

.page-title h1 {
    font-size: 24px;
    font-weight: 700;
}

.page-title .breadcrumbs ol {
    display: flex;
    flex-wrap: wrap;
    list-style: none;
    padding: 0;
    margin: 0;
    font-size: 14px;
    font-weight: 400;
}

.page-title .breadcrumbs ol li + li {
    padding-left: 10px;
}

.page-title .breadcrumbs ol li + li::before {
    content: "/";
    display: inline-block;
    padding-right: 10px;
    color: color-mix(in srgb, var(--default-color), transparent 70%);
}

/*--------------------------------------------------------------
# Global Sections
--------------------------------------------------------------*/
section,
.section {
    color: var(--default-color);
    background-color: var(--background-color);
    padding: 60px 0;
    overflow: clip;
}

/*--------------------------------------------------------------
# Global Section Titles
--------------------------------------------------------------*/
.section-title {
    text-align: center;
    padding-bottom: 60px;
    position: relative;
}

.section-title h2 {
    font-size: 32px;
    font-weight: 700;
    position: relative;
}

.section-title h2:before,
.section-title h2:after {
    content: "";
    width: 50px;
    height: 2px;
    background: var(--accent-color);
    display: inline-block;
}

.section-title h2:before {
    margin: 0 15px 10px 0;
}

.section-title h2:after {
    margin: 0 0 10px 15px;
}

.section-title p {
    margin-bottom: 0;
}

/*--------------------------------------------------------------
# Hero Section
--------------------------------------------------------------*/
.hero {
    min-height: 100vh;
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
}

.hero .background-elements {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 1;
    overflow: hidden;
}

.hero .background-elements .bg-circle {
    position: absolute;
    border-radius: 50%;
    background: linear-gradient(
        45deg,
        color-mix(in srgb, var(--accent-color), transparent 90%),
        color-mix(in srgb, var(--accent-color), transparent 95%)
    );
    animation: float 6s ease-in-out infinite;
}

.hero .background-elements .bg-circle.circle-1 {
    width: 300px;
    height: 300px;
    top: 10%;
    right: 10%;
    animation-delay: 0s;
}

.hero .background-elements .bg-circle.circle-2 {
    width: 200px;
    height: 200px;
    bottom: 20%;
    left: 5%;
    animation-delay: 2s;
}

.hero .hero-content {
    position: relative;
    width: 100%;
    z-index: 2;
}

.hero .container {
    position: relative;
    z-index: 3;
}

.hero .hero-text h1 {
    font-size: 72px;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 15px;
    color: var(--heading-color);
}

.hero .hero-text h1 .accent-text {
    color: var(--accent-color);
    position: relative;
}

.hero .hero-text h1 .accent-text::after {
    content: "";
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--accent-color),
        color-mix(in srgb, var(--accent-color), transparent 50%)
    );
}

.hero .hero-text h2 {
    font-size: 32px;
    font-weight: 600;
    color: var(--heading-color);
    margin-bottom: 10px;
}

.hero .hero-text .lead {
    font-size: 24px;
    margin-bottom: 20px;
    color: var(--default-color);
}

.hero .hero-text .lead span {
    color: var(--accent-color);
    font-weight: 600;
    border-bottom: 2px solid var(--accent-color);
    padding-bottom: 2px;
}

.hero .hero-text .description {
    font-size: 18px;
    line-height: 1.6;
    color: color-mix(in srgb, var(--default-color), transparent 20%);
    margin-bottom: 40px;
    max-width: 500px;
}

.hero .hero-actions {
    display: flex;
    gap: 20px;
    margin-bottom: 40px;
    flex-wrap: wrap;
}

.hero .hero-actions .btn {
    padding: 14px 30px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
    border: 2px solid;
}

.hero .hero-actions .btn.btn-primary {
    background-color: var(--accent-color);
    color: var(--contrast-color);
    border-color: var(--accent-color);
}

.hero .hero-actions .btn.btn-primary:hover {
    background-color: color-mix(in srgb, var(--accent-color), black 10%);
    transform: translateY(-2px);
    box-shadow: 0 8px 25px
        color-mix(in srgb, var(--accent-color), transparent 70%);
}

.hero .hero-actions .btn.btn-outline {
    background-color: transparent;
    color: var(--accent-color);
    border-color: var(--accent-color);
}

.hero .hero-actions .btn.btn-outline:hover {
    background-color: var(--accent-color);
    color: var(--contrast-color);
    transform: translateY(-2px);
}

.hero .social-links {
    display: flex;
    gap: 20px;
}

.hero .social-links a {
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: var(--surface-color);
    color: color-mix(in srgb, var(--default-color), transparent 40%);
    border-radius: 50%;
    font-size: 20px;
    transition: all 0.3s ease;
}

.hero .social-links a:hover {
    color: var(--contrast-color);
    background-color: var(--accent-color);
    transform: translateY(-3px);
    box-shadow: 0 8px 25px
        color-mix(in srgb, var(--accent-color), transparent 70%);
}

.hero .hero-visual {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.hero .hero-visual .profile-container {
    position: relative;
    width: 400px;
    height: 400px;
}

.hero .hero-visual .profile-container .profile-background {
    position: absolute;
    top: 15px;
    left: 15px;
    width: 100%;
    height: 100%;
    background: color-mix(in srgb, var(--accent-color), transparent 90%);
    border-radius: 30px;
    z-index: 1;
}

.hero .hero-visual .profile-container .profile-image {
    position: relative;
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 30px;
    z-index: 2;
}

@keyframes float {
    0%,
    100% {
        transform: translateY(0px);
    }

    50% {
        transform: translateY(-20px);
    }
}

@keyframes floatIcon {
    0%,
    100% {
        transform: translateY(0px) rotate(0deg);
    }

    50% {
        transform: translateY(-10px) rotate(5deg);
    }
}

@media (max-width: 992px) {
    .hero .hero-text {
        text-align: center;
        margin-bottom: 50px;
    }

    .hero .hero-text h1 {
        font-size: 56px;
    }

    .hero .hero-text h2 {
        font-size: 28px;
    }

    .hero .hero-text .lead {
        font-size: 20px;
    }

    .hero .hero-visual .profile-container {
        width: 350px;
        height: 350px;
    }
}

@media (max-width: 768px) {
    .hero .hero-text h1 {
        font-size: 42px;
    }

    .hero .hero-text h2 {
        font-size: 24px;
    }

    .hero .hero-text .lead {
        font-size: 18px;
    }

    .hero .hero-text .description {
        font-size: 16px;
    }

    .hero .hero-actions {
        justify-content: center;
    }

    .hero .hero-actions .btn {
        padding: 12px 25px;
        font-size: 14px;
    }

    .hero .hero-visual .profile-container {
        width: 300px;
        height: 300px;
    }

    .hero .background-elements .bg-circle.circle-1 {
        width: 200px;
        height: 200px;
    }

    .hero .background-elements .bg-circle.circle-2 {
        width: 150px;
        height: 150px;
    }

    .hero .background-elements .bg-circle.circle-3 {
        width: 100px;
        height: 100px;
    }
}

/*--------------------------------------------------------------
# About Section
--------------------------------------------------------------*/
.about .profile-card {
    background: linear-gradient(
        135deg,
        var(--surface-color) 0%,
        color-mix(in srgb, var(--surface-color), var(--accent-color) 5%) 100%
