}

.about .profile-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: linear-gradient(
        90deg,
        var(--accent-color),
        color-mix(in srgb, var(--accent-color), var(--heading-color) 30%)
    );
}

