    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--surface-color);
    clip-path: polygon(70% 0, 100% 30%, 100% 100%, 0 100%, 0 0);
    z-index: -1;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.services .service-card:hover {
    border-color: transparent;
}

.services .service-card:hover::before {
    opacity: 1;
    visibility: visible;
    background-color: color-mix(in srgb, var(--accent-color), transparent 90%);
}

.services .service-card:hover h3 a {
    color: var(--accent-color);
}

.services .service-card:hover h3 a:hover {
    color: var(--accent-color);
}

.services .service-card:hover p {
    color: color-mix(in srgb, var(--default-color), transparent 20%);
}

.services .service-card:hover .card-action {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.services .service-card:hover .service-icon i {
    transform: scale(1.1);
}

@media (max-width: 768px) {
    .services .service-card {
        padding: 150px 25px 25px;
    }

    .services .service-card h3 {
        font-size: 24px;
    }

    .services .service-card .service-icon {
        position: absolute;
        top: 40px;
        left: 25px;
    }
}

@media (max-width: 768px) {
    .services {
        padding: 70px 0 50px;
    }
}

/*--------------------------------------------------------------
# Testimonials Section
--------------------------------------------------------------*/
.testimonials .testimonial-masonry {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    position: relative;
}

.testimonials .testimonial-masonry::before {
    content: "";
    position: absolute;
    width: 100%;
    height: 100%;
    background: radial-gradient(
        circle at center,
        color-mix(in srgb, var(--accent-color), transparent 95%),
        transparent
    );
    opacity: 0.5;
    z-index: -1;
}

.testimonials .testimonial-item:nth-child(3n-1) {
    margin-top: 3rem;
}

.testimonials .testimonial-item:nth-child(3n) {
    margin-top: 1.5rem;
}

.testimonials .testimonial-item.highlight .testimonial-content {
    background-color: color-mix(in srgb, var(--accent-color), transparent 92%);
    border: 1px solid color-mix(in srgb, var(--accent-color), transparent 70%);
}

.testimonials .testimonial-item.highlight .testimonial-content .quote-pattern {
    background-color: color-mix(in srgb, var(--accent-color), transparent 85%);
}

.testimonials
    .testimonial-item.highlight
    .testimonial-content
    .quote-pattern
    i {
    color: var(--accent-color);
}

.testimonials .testimonial-content {
    background-color: var(--surface-color);
    border-radius: 20px;
    padding: 2rem;
    position: relative;
    transition: all 0.3s ease;
    border: 1px solid color-mix(in srgb, var(--default-color), transparent 92%);
}

.testimonials .testimonial-content:hover {
    transform: translateY(-5px);
}

.testimonials .testimonial-content p {
    font-size: 1rem;
    line-height: 1.7;
    margin: 1.5rem 0;
    position: relative;
}

.testimonials .quote-pattern {
    position: absolute;
    top: -1.25rem;
    left: 2rem;
    width: 2.5rem;
    height: 2.5rem;
    background-color: var(--surface-color);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid color-mix(in srgb, var(--default-color), transparent 92%);
}

.testimonials .quote-pattern i {
    font-size: 1.25rem;
    color: var(--accent-color);
}

.testimonials .client-info {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid
        color-mix(in srgb, var(--default-color), transparent 92%);
}

.testimonials .client-image {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    overflow: hidden;
    flex-shrink: 0;
}

.testimonials .client-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.testimonials .client-details h3 {
    font-size: 1.125rem;
    margin-bottom: 0.25rem;
}

.testimonials .client-details .position {
    font-size: 0.875rem;
    color: color-mix(in srgb, var(--heading-color), transparent 40%);
}

@media (max-width: 1199.98px) {
    .testimonials .testimonial-masonry {
        grid-template-columns: repeat(2, 1fr);
        gap: 1.5rem;
    }

    .testimonials .testimonial-item:nth-child(3n-1),
    .testimonials .testimonial-item:nth-child(3n) {
        margin-top: 0;
    }

    .testimonials .testimonial-item:nth-child(even) {
        margin-top: 2rem;
    }
}

@media (max-width: 767.98px) {
    .testimonials .testimonial-masonry {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .testimonials .testimonial-item:nth-child(even) {
        margin-top: 0;
    }

    .testimonials .testimonial-content {
        padding: 1.5rem;
    }

    .testimonials .testimonial-content p {
        font-size: 0.9375rem;
        margin: 1.25rem 0;
    }

    .testimonials .quote-pattern {
        width: 2.25rem;
        height: 2.25rem;
        top: -1.125rem;
    }

    .testimonials .quote-pattern i {
        font-size: 1.125rem;
    }

    .testimonials .client-info {
        margin-top: 1.25rem;
        padding-top: 1.25rem;
    }

    .testimonials .client-image {
        width: 45px;
        height: 45px;
    }

    .testimonials .client-details h3 {
        font-size: 1rem;
    }

    .testimonials .client-details .position {
        font-size: 0.8125rem;
    }
}

