/* ===== FLOATING WHATSAPP ===== */
/* ===== FLOATING WHATSAPP - GLASSMORPHISM ===== */
.floating-wa {
  position: fixed;
  bottom: 75px;
  right: 10px;
  z-index: 9999;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(37, 211, 102, 0.15);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(37, 211, 102, 0.3);
  border-radius: 50px;
  padding: 10px 20px 10px 10px;
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 20px rgba(37, 211, 102, 0.2);
  animation: waPulse 2.5s ease infinite;
}

.floating-wa-icon {
  width: 42px;
  height: 42px;
  background: #25d366;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  color: #fff;
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  flex-shrink: 0;
}

.floating-wa-text {
  color: #25d366;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  letter-spacing: 0.5px;
  opacity: 1;
  max-width: 100px;
  transition: opacity 0.2s ease 0.4s, max-width 0.5s cubic-bezier(0.4, 0, 0.2, 1) 0.1s, margin 0.5s ease, padding 0.5s ease;
}

.floating-wa:hover {
  background: rgba(37, 211, 102, 0.25);
  box-shadow: 0 6px 25px rgba(37, 211, 102, 0.35);
  transform: translateY(-3px);
  animation: none;
  transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.floating-wa:hover .floating-wa-icon {
  transform: rotate(15deg) scale(1.1);
  transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Heartbeat halus */
@keyframes waPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(37, 211, 102, 0.5);
  }
  70% {
    box-shadow: 0 0 0 14px rgba(37, 211, 102, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(37, 211, 102, 0);
  }
}
/* Saat scroll — mengecil */
/* Saat scroll — mengecil dengan efek glass */
.floating-wa.scrolled {
  padding: 8px;
  border-radius: 50%;
  gap: 0;
  background: rgba(37, 211, 102, 0.15);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(37, 211, 102, 0.3);
  box-shadow: 0 4px 20px rgba(37, 211, 102, 0.2);
}

.floating-wa.scrolled .floating-wa-icon {
  width: 36px;
  height: 36px;
  font-size: 18px;
  background: #25d366;
}

.floating-wa.scrolled .floating-wa-text {
  opacity: 0;
  max-width: 0;
  overflow: hidden;
  padding: 0;
  margin: 0;
  transition: opacity 0.15s ease, max-width 0.5s cubic-bezier(0.4, 0, 0.2, 1) 0.05s, margin 0.5s ease, padding 0.5s ease;
}

.floating-wa.scrolled:hover {
  background: rgba(37, 211, 102, 0.25);
  box-shadow: 0 6px 25px rgba(37, 211, 102, 0.35);
  transform: translateY(-3px) scale(1.05);
}

