:root {
  --w-column: 200px;
  /* pastikan var ini ada di project-mu */
  /* --nav-color: #659cdf55; */
}

/* ====== CAROUSEL WRAPPER ====== */
.product-detail-carousel {
  height: 100vh;
  overflow: hidden;
  position: relative;
}

/* ====== SWIPER BASE ====== */
.product-detail-carousel .swiper {
  width: 100%;
  height: 100%;
}

/* jadikan wrapper Swiper mengikuti layout lama */
.product-detail-carousel .swiper-wrapper,
.product-detail-carousel .product-detail-list {
  width: min(1200px, 90vw);
  margin: auto;
  height: 100%;
  position: relative;
  display: flex; /* penting untuk swiper */
  align-items: stretch;
}

/* setiap slide Swiper */
.product-detail-carousel .swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: 100%;
  position: relative; /* pembungkus item */
  display: flex;
}

/* ====== ITEM (di dalam tiap .swiper-slide) ====== */
.product-detail-carousel .product-detail-item {
  /* DULU: absolute + inset:0 → bikin numpuk; sekarang relatif */
  position: relative;
  inset: auto;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  /* state default (non-aktif), biar ada depth tapi tetap terlihat */
  opacity: 0.6;
  transform: translateZ(0) scale(0.98);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

/* slide aktif dari Swiper → ganti efek 'aktif' lama */
.product-detail-carousel .swiper-slide-active .product-detail-item {
  opacity: 1;
  transform: translateZ(0) scale(1);
}

/* ====== FIGURE & IMAGE ====== */
.product-detail-carousel .product-detail-item figure {
  position: absolute;
  width: 75%;
  top: 50%;
  left: 5%;
  transform: translateY(-50%);
}

.product-detail-carousel .product-detail-item figure img {
  width: 80%;
  transform: rotate(-30deg);
  transition: transform 0.5s ease;
}

/* saat slide aktif, pakai efek rotasi seperti CSS lamamu */
.product-detail-carousel .swiper-slide-active .product-detail-item figure img {
  transform: rotate(5deg);
}

.product-detail-carousel .product-detail-item figure::before {
  content: "";
  position: absolute;
  background-color: #0b0b1b;
  width: 100%;
  height: 100px;
  top: 150%;
  left: 50px;
  border-radius: 50%;
  filter: blur(50px);
}

/* ====== CONTENT ====== */
.product-detail-carousel .product-detail-content {
  position: absolute;
  z-index: 20;
  top: 20%;
  width: 70%;
  height: 100%;
  right: var(--w-column);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: end;
  gap: 20px;
  /* animasi masuk (gantikan .active lama) */
  opacity: 0;
  transform: translateX(50px);
  transition: opacity 0.5s ease 0.2s, transform 0.5s ease 0.2s;
}

.product-detail-carousel .swiper-slide-active .product-hero-name,
.product-detail-carousel .swiper-slide-active .product-detail-content {
  opacity: 1;
  transform: translateX(0);
}

.product-detail-carousel .product-detail-content .product-detail-category {
  font-weight: 500;
}

.product-detail-carousel .product-hero-name {
  position: absolute;
  z-index: -1;
  bottom: 25%;
  width: 70%;
  height: 100%;
  right: var(--w-column);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: end;
  gap: 20px;
  /* animasi masuk (gantikan .active lama) */
  opacity: 0;
  transform: translateX(50px);
  transition: opacity 0.5s ease 0.2s, transform 0.5s ease 0.2s;
}

.product-detail-carousel .product-hero-name h2 {
  font-family: "League Gothic";
  font-size: 20rem;
  font-weight: 900;
  line-height: 1em;
}

.product-detail-carousel .product-detail-content .product-detail-description {
  align-items: center;
  color: rgba(255, 255, 255, 0.5333333333);
  max-width: 400px;
  font-size: small;
  text-align: right;
}

.product-detail-carousel .product-detail-content .product-detail-description i {
  height: 50px;
  color: #ffea7c;
  font-size: 2em;
  border: 1px solid #659cdf;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* ====== MORE BUTTONS ====== */
.product-detail-carousel .product-detail-more {
  display: grid;
  grid-template-columns: repeat(2, 120px);
  gap: 20px;
  grid-template-rows: 35px;
}

.product-detail-carousel .product-detail-more button {
  border-radius: 30px;
  font-family: "League Gothic";
  text-transform: uppercase;
  color: #fff;
  background-color: transparent;
  border: none;
  position: relative;
}

.product-detail-carousel .product-detail-more button:nth-child(1) {
  background-image: linear-gradient(to right, #81baa0, #46a39c);
}

.product-detail-carousel .product-detail-more button:nth-child(2) {
  border: 2px solid transparent;
  color: var(--surface-color);
  background: var(--accent-color);
}

.product-detail-carousel .product-detail-more button:nth-child(2) i {
  margin-right: 10px;
}

/* ====== DEKOR GARIS (dipindah ke wrapper swiper) ====== */
.product-detail-carousel .swiper-wrapper::after,
.product-detail-carousel .product-detail-list::after {
  content: "";
  position: absolute;
  right: var(--w-column);
  width: var(--w-column);
  height: 100%;
  border-left: 1px solid var(--nav-color);
  border-right: 1px solid var(--nav-color);
  pointer-events: none;
}

.product-detail-carousel .swiper-wrapper::before,
.product-detail-carousel .product-detail-list::before {
  content: "";
  position: absolute;
  z-index: 10;
  height: var(--w-column);
  width: 100%;
  top: 52%;
  border-top: 1px solid var(--nav-color);
  border-bottom: 1px solid var(--nav-color);
  pointer-events: none;
}

/* ====== ARROWS (kalau pakai tombol custom kamu) ====== */
.product-detail-carousel .product-detail-arrows {
  width: 100%;
  padding: 1rem;
  display: flex;
  justify-content: space-between;
  position: absolute;
  top: 52%;
  left: 50%;
  transform: translate(-50%, -25px);
  pointer-events: none;
  z-index: 100;
}

.product-detail-carousel .product-detail-arrows button {
  top: 60%;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 1px solid rgba(101, 156, 223, 0.3333333333);
  background-color: #232442;
  color: rgba(255, 255, 255, 0.4666666667);
  font-size: large;
  cursor: pointer;
  pointer-events: auto;
  transition: 0.5s;
}

.product-detail-carousel .product-detail-arrows button:hover {
  border: 1px solid #659cdf;
  color: #fff;
}

/* ====== INDICATORS (kalau pakai pagination custom kamu) ====== */
.product-detail-carousel .product-detail-indicators {
  position: absolute;
  top: 52%;
  height: var(--w-column);
  width: min(1200px, 90vw);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  pointer-events: none;
  justify-content: end;
  gap: 10px;
}

.product-detail-carousel .product-detail-indicators .product-detail-number {
  font-family: "League Gothic";
  font-size: 7vw;
}

.product-detail-carousel .product-detail-indicators ul {
  display: flex;
  gap: 10px;
}

.product-detail-carousel .product-detail-indicators ul li {
  width: 50px;
  height: 5px;
  background-color: #659cdf;
  border-radius: 10px;
  pointer-events: auto;
  cursor: pointer;
  transition: 0.5s;
  list-style: none;
}

.product-detail-carousel .product-detail-indicators ul li.active {
  background-color: yellow;
}

/* tombol custom */
.product-swiper-button {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 20;
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
