/* Dropdown list */
.tesdrive-section .select2-container .select2-dropdown {
  background-color: var(--surface-color);
  border: 1px solid color-mix(in srgb, var(--default-color), transparent 80%);
  border-radius: 5px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  margin-top: 4px;
}

/* Item dalam dropdown */
.tesdrive-section .select2-container .select2-results__option {
  padding: 10px 15px;
  font-size: 14px;
  color: var(--default-color);
}

/* Hover dan pilihan aktif */
.tesdrive-section .select2-container .select2-results__option--highlighted {
  background-color: var(--accent-color);
  color: var(--contrast-color);
}

/* Selected item */
.tesdrive-section .select2-container .select2-results__option[aria-selected=true] {
  background-color: color-mix(in srgb, var(--accent-color), #000 10%);
  color: var(--contrast-color);
}

/* Multi select (jika nanti kamu pakai) */
.tesdrive-section .select2-container .select2-selection--multiple {
  min-height: 50px;
  background-color: var(--surface-color);
  border: 1px solid color-mix(in srgb, var(--default-color), transparent 80%);
  border-radius: 5px;
  color: var(--default-color);
  font-size: 14px;
}

.tesdrive-section .select2-container .select2-selection--multiple .select2-selection__choice {
  background-color: var(--accent-color);
  color: var(--contrast-color);
  border: none;
  border-radius: 3px;
  margin-top: 6px;
}

.tesdrive-section .select2-container .select2-selection--multiple .select2-selection__choice__remove {
  color: var(--contrast-color);
  margin-right: 4px;
}

/* Hilangkan garis (outline) saat fokus di input pencarian dropdown */
.tesdrive-section .select2-container .select2-search--dropdown .select2-search__field:focus {
  outline: none;
  box-shadow: none;
  border-color: var(--accent-color);
  /* opsional, bisa juga transparent */
}

/* Atur ulang border input search agar menyatu dengan tema */
.tesdrive-section .select2-container .select2-search--dropdown .select2-search__field {
  border: 1px solid color-mix(in srgb, var(--default-color), transparent 80%);
  background-color: var(--surface-color);
  color: var(--default-color);
  border-radius: 5px;
  padding: 8px 10px;
  font-size: 14px;
}

.tesdrive-section .select2-container .select2-search--dropdown {
  padding: 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--default-color), transparent 80%);
}